import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.wVcpyw2-.js";const p=JSON.parse('{"title":"进入管理后台","description":"灵萌管理后台登录入口、界面说明、菜单找不到时的排查，以及常用配置速查表。","frontmatter":{"title":"进入管理后台","description":"灵萌管理后台登录入口、界面说明、菜单找不到时的排查，以及常用配置速查表。"},"headers":[],"relativePath":"guide/admin-access.md","filePath":"guide/admin-access.md","lastUpdated":1785051348000}'),s={name:"guide/admin-access.md"};function n(o,t,i,l,h,g){return r(),d("div",null,[...t[0]||(t[0]=[e(`<h1 id="进入管理后台" tabindex="-1">进入管理后台 <a class="header-anchor" href="#进入管理后台" aria-label="Permalink to &quot;进入管理后台&quot;">​</a></h1><h2 id="访问地址" tabindex="-1">访问地址 <a class="header-anchor" href="#访问地址" aria-label="Permalink to &quot;访问地址&quot;">​</a></h2><p>管理后台为 <strong>H5 网页</strong>，请在电脑浏览器打开（推荐 Chrome / Edge）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的域名/pages_admin/index/index</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">仅支持 H5</p><p>不要在微信小程序里打开管理后台。手机浏览器可以应急，复杂配置（尤其 UI 编辑器）请用电脑。</p></div><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><p>使用初始化向导中设置的<strong>超级管理员</strong>账号。</p><p>首次部署若未改密码，默认为 <code>admin</code> / <code>admin123</code>，<strong>登录后请立即修改密码</strong>。</p><p>给同事开后台：见 <a href="/config/admin-permissions">账号权限与权限模板</a>。</p><h2 id="界面说明" tabindex="-1">界面说明 <a class="header-anchor" href="#界面说明" aria-label="Permalink to &quot;界面说明&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────┬──────────────────────────────────┐</span></span>
<span class="line"><span>│  左侧菜单    │  右侧工作区（列表 / 表单 / Tab）    │</span></span>
<span class="line"><span>│  （可折叠）  │                                   │</span></span>
<span class="line"><span>└─────────────┴──────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>区域</th><th>作用</th></tr></thead><tbody><tr><td><strong>左侧菜单</strong></td><td>按业务分组：系统设置、区域管理、通知、AI、商户等</td></tr><tr><td><strong>顶栏</strong></td><td>当前管理员、退出、主题</td></tr><tr><td><strong>工作区</strong></td><td>具体配置或数据列表</td></tr></tbody></table><p>完整菜单说明见 <strong><a href="/guide/admin-menu-map">后台菜单地图</a></strong>。</p><h2 id="菜单找不到某项" tabindex="-1">菜单找不到某项？ <a class="header-anchor" href="#菜单找不到某项" aria-label="Permalink to &quot;菜单找不到某项？&quot;">​</a></h2><p>按顺序检查：</p><ol><li><strong>系统设置 → 我的模块</strong> — 功能是否已开通（<a href="/config/my-modules">说明</a>）</li><li><strong>系统设置 → 账号权限</strong> — 当前账号是否勾了该菜单（<a href="/config/admin-permissions">说明</a>）</li><li>是否显示 <strong>内测中</strong> — 产品尚未对你站点开放，联系交付方</li><li>退出重新登录一次</li></ol><h2 id="常用入口速查" tabindex="-1">常用入口速查 <a class="header-anchor" href="#常用入口速查" aria-label="Permalink to &quot;常用入口速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想…</th><th>菜单路径</th><th>文档</th></tr></thead><tbody><tr><td>配微信 / 支付 / 存储 / 地图</td><td>系统设置 → <strong>系统配置</strong></td><td><a href="/config/system-settings">系统配置</a></td></tr><tr><td>改网站名称 Logo</td><td>系统设置 → <strong>网站信息</strong></td><td><a href="/config/site-info">网站信息</a></td></tr><tr><td>看开通了哪些功能</td><td>系统设置 → <strong>我的模块</strong></td><td><a href="/config/my-modules">我的模块</a></td></tr><tr><td>给同事开后台权限</td><td>系统设置 → <strong>账号权限</strong></td><td><a href="/config/admin-permissions">账号权限</a></td></tr><tr><td>配敏感词</td><td>系统设置 → <strong>全局违禁词</strong></td><td><a href="/config/forbidden-words">违禁词</a></td></tr><tr><td>配 SMTP 邮箱</td><td>系统设置 → <strong>邮箱配置</strong></td><td><a href="/config/email">邮箱</a></td></tr><tr><td>新增校区</td><td>区域管理 → <strong>区域列表</strong></td><td><a href="/config/region">区域</a></td></tr><tr><td>控制注册登录方式</td><td>区域管理 → <strong>用户配置</strong></td><td><a href="/config/user-rules">用户规则</a></td></tr><tr><td>控制发帖审核</td><td>区域管理 → <strong>笔记配置</strong></td><td><a href="/features/circle-note">圈子与笔记</a></td></tr><tr><td>改首页布局</td><td>UI管理 → <strong>页面配置</strong></td><td><a href="/features/ui-editor/">UI 编辑器</a></td></tr><tr><td>改底部导航</td><td>UI管理 → <strong>TabBar配置</strong></td><td><a href="/features/ui-editor/tabbar">TabBar</a></td></tr><tr><td>发通知、配模板</td><td>通知控制台 → <strong>事件模板</strong></td><td><a href="/features/notification">通知</a></td></tr><tr><td>对接钉钉/企微机器人</td><td>通知控制台 → <strong>机器人推送</strong></td><td><a href="/features/open-stream">对外事件流</a></td></tr><tr><td>配 AI</td><td>AI中台 → <strong>供应商管理</strong></td><td><a href="/features/ai">AI 中台</a></td></tr><tr><td>智能评论</td><td>评论运营 → <strong>智能评论配置</strong></td><td><a href="/features/ai-comment">智能评论</a></td></tr><tr><td>推广拉新</td><td>平台推广 → <strong>推广配置</strong></td><td><a href="/features/promotion">推广员</a></td></tr><tr><td>发优惠券</td><td>平台推广 → <strong>券模板</strong></td><td><a href="/features/coupon">营销券</a></td></tr><tr><td>查流水 / 审提现</td><td>财务管理 → <strong>…</strong></td><td><a href="/features/finance">财务</a></td></tr><tr><td>开外卖</td><td>商户管理 → <strong>区域外卖配置</strong></td><td><a href="/features/takeaway">外卖</a></td></tr><tr><td>开跑腿 / 服务表单</td><td>商户管理 / UI 服务表单</td><td><a href="/features/errand">跑腿</a></td></tr></tbody></table><h2 id="配置的两层逻辑-必懂" tabindex="-1">配置的两层逻辑（必懂） <a class="header-anchor" href="#配置的两层逻辑-必懂" aria-label="Permalink to &quot;配置的两层逻辑（必懂）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td><strong>全站</strong></td><td>所有区域共用</td><td>系统配置里的微信 AppID、存储</td></tr><tr><td><strong>区域</strong></td><td>每个校区可不同</td><td>用户配置、笔记配置、外卖是否开通</td></tr></tbody></table><p>区域编号 <strong>0 = 平台默认</strong>：其它区域没单独配时，继承这一份。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>某区域已经建了专属配置，却把「启用」关掉，通常<strong>不会</strong>自动退回平台默认，而是直接拦截。详见 <a href="/config/user-rules">用户规则</a>。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li><a href="/guide/admin-menu-map">后台菜单地图</a> — 浏览全部菜单</li><li><a href="/config/system-settings">系统配置总览</a> — 先把微信/存储/地图配通</li><li><a href="/config/region">区域管理</a> + <a href="/config/user-rules">用户规则</a></li><li><a href="/features/ui-editor/">UI 编辑器</a> — 搭首页</li><li><a href="/ops/checklist">上线检查清单</a></li></ol>`,24)])])}const f=a(s,[["render",n]]);export{p as __pageData,f as default};
